local function rbx_append_stdin(text)
    rbx_stdin_buf = rbx_stdin_buf .. (type(text) == "string" and text or "")
end
local function rbx_set_env(tbl)
    rbx_env_entries = {}
    if type(tbl) ~= "table" then return end
    for k, v in pairs(tbl) do
        table.insert(rbx_env_entries, tostring(k) .. "=" .. tostring(v))
    end
end
FUNC_LIST[0] = --[[ __cxa_throw ]] function(ptr, tinfo, dtor)
    error("[RBX-CPP] uncaught C++ exception", 0)
end
FUNC_LIST[1] = --[[ environ_sizes_get ]] function(count_ptr, size_ptr)
    local count, bufsize = 0, 0
    for _, e in ipairs(rbx_env_entries) do
        count = count + 1
        bufsize = bufsize + #e + 1
    end
    rt_store_i32(memory_at_0, count_ptr, count)
    rt_store_i32(memory_at_0, size_ptr, bufsize)
    return 0
end
FUNC_LIST[2] = --[[ environ_get ]] function(env_ptr, buf_ptr)
    local p = buf_ptr
    for i, e in ipairs(rbx_env_entries) do
        store_string(memory_at_0, p, e .. "\0", #e + 1)
        rt_store_i32(memory_at_0, env_ptr + (i - 1) * 4, p)
        p = p + #e + 1
    end
    return 0
end
FUNC_LIST[3] = --[[ emscripten_resize_heap ]] function(requested)
    local current_pages = rt_allocator_size(memory_at_0)
    local needed_pages = math_ceil(requested / 65536) - current_pages
    if needed_pages <= 0 then return 1 end
    if current_pages + needed_pages > memory_at_0.max then
        memory_at_0.max = current_pages + needed_pages
    end
    return rt_allocator_grow(memory_at_0, needed_pages) ~= 0xFFFFFFFF and 1 or 0
end
FUNC_LIST[4] = --[[ fd_seek ]] function(fd, ol, oh, whence, np) return 70 end
FUNC_LIST[5] = --[[ fd_write ]] function(fd, iov, iovcnt, nwritten)
    local total = 0
    local data = ""
    for i = 0, iovcnt - 1 do
        local ptr = rt_load_i32(memory_at_0, iov + i * 8)
        local len = rt_load_i32(memory_at_0, iov + i * 8 + 4)
        if len > 0 then
            data = data .. load_string(memory_at_0, ptr, len)
            total = total + len
        end
    end
    if fd == 2 then
        rbx_stderr_buf = rbx_stderr_buf .. data
        local nl = string.find(rbx_stderr_buf, "\n")
        while nl do
            warn(string.sub(rbx_stderr_buf, 1, nl - 1))
            rbx_stderr_buf = string.sub(rbx_stderr_buf, nl + 1)
            nl = string.find(rbx_stderr_buf, "\n")
        end
    else
        rbx_stdout_buf = rbx_stdout_buf .. data
        local nl = string.find(rbx_stdout_buf, "\n")
        while nl do
            print(string.sub(rbx_stdout_buf, 1, nl - 1))
            rbx_stdout_buf = string.sub(rbx_stdout_buf, nl + 1)
            nl = string.find(rbx_stdout_buf, "\n")
        end
    end
    rt_store_i32(memory_at_0, nwritten, total)
    return 0
end
FUNC_LIST[6] = --[[ fd_read ]] function(fd, iov, iovcnt, nread)
    if fd ~= 0 then rt_store_i32(memory_at_0, nread, 0) return 0 end
    local total = 0
    for i = 0, iovcnt - 1 do
        if #rbx_stdin_buf == 0 then break end
        local ptr = rt_load_i32(memory_at_0, iov + i * 8)
        local len = rt_load_i32(memory_at_0, iov + i * 8 + 4)
        if len > 0 then
            local n = math.min(len, #rbx_stdin_buf)
            local chunk = string.sub(rbx_stdin_buf, 1, n)
            store_string(memory_at_0, ptr, chunk, n)
            rbx_stdin_buf = string.sub(rbx_stdin_buf, n + 1)
            total = total + n
            if n < len then break end
        end
    end
    rt_store_i32(memory_at_0, nread, total)
    return 0
end
FUNC_LIST[7] = --[[ fd_close ]] function(fd) return 0 end
FUNC_LIST[8] = --[[ _abort_js ]] function() error("[RBX-CPP] abort() called", 0) end
FUNC_LIST[9] = --[[ _tzset_js ]] function() end

--// lua_call
FUNC_LIST[11] = function (code)
    code = load_string(memory_at_0, code, NamedFunctionList.strlen(code))
    local loaded = loadstring(code)
    local ret = loaded and loaded() or ""
    if type(ret) ~= "string" then
        ret = tostring(ret)
    end

    local addr = NamedFunctionList.malloc(#ret + 1)
    store_string(memory_at_0, addr, ret .. "\0", #ret + 1)
    return addr
end

--// Initialize
run_init_code()
memory_at_0 = MEMORY_LIST[0]
NamedFunctionList.__wasm_call_ctors()

local function convertString(s)
    if type(s) == "string" then
        local addr = NamedFunctionList.malloc(#s + 1)
        store_string(memory_at_0, addr, s .. "\0", #s + 1)
        return addr
    else
        return load_string(memory_at_0, s, NamedFunctionList.strlen(s))
    end
end

-- Pack a Lua list of strings into a C-style argv (array of char* in linear
-- memory) and return (argc, argv_ptr). Memory is leaked (mirrors libc); the
-- WASM module typically lives for the runtime of the script.
local function rbx_pack_argv(args)
    local argc = #args
    local addrs = {}
    for i = 1, argc do
        local s = tostring(args[i])
        local addr = NamedFunctionList.malloc(#s + 1)
        store_string(memory_at_0, addr, s .. "\0", #s + 1)
        addrs[i] = addr
    end
    -- argv is a NULL-terminated array of pointers (4 bytes each in wasm32).
    local argv = NamedFunctionList.malloc((argc + 1) * 4)
    for i = 1, argc do
        rt_store_i32(memory_at_0, argv + (i - 1) * 4, addrs[i])
    end
    rt_store_i32(memory_at_0, argv + argc * 4, 0)
    return argc, argv
end

-- Run main with the given arguments. Call setStdin/setEnv BEFORE this so
-- stdin reads and getenv() see what you provided.
local function rbx_run_main(...)
    local args = {...}
    if #args == 0 then args = {"rbx-cpp"} end
    local argc, argv = rbx_pack_argv(args)
    local code = NamedFunctionList.main(argc, argv)
    if rbx_flush_streams then rbx_flush_streams() end
    return code
end

--// Return
return {
    --// Exported functions
    malloc = NamedFunctionList.malloc,
lua_call = NamedFunctionList.lua_call,
strlen = NamedFunctionList.strlen,
main = NamedFunctionList.main,

    --// Wasynth related utilities
    NamedFunctionList = NamedFunctionList;
    convertString = convertString;
    flushStreams = rbx_flush_streams;
    setStdin = rbx_set_stdin;
    appendStdin = rbx_append_stdin;
    setEnv = rbx_set_env;
    FUNC_LIST = FUNC_LIST;
run = rbx_run_main;
}